-- Keep digital-content settlement idempotent and aligned with the seller ledger.
CREATE OR REPLACE FUNCTION public.settle_digital_content_checkout(p_order_id uuid, p_provider text, p_provider_payment_id text, p_payment_status payment_status, p_payment_method text DEFAULT NULL::text, p_provider_fee numeric DEFAULT 0)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare\n  v_order public.orders%rowtype;\n  v_payment public.payments%rowtype;\n  v_meta jsonb;\n  v_product public.digital_content_products%rowtype;\n  v_sale public.digital_content_sales%rowtype;\n  v_rule public.fans_fee_rules%rowtype;\n  v_platform_fee numeric := 0;\n  v_provider_fee numeric := greatest(coalesce(p_provider_fee,0),0);\n  v_owner_amount numeric := 0;\n  v_total_fees numeric := 0;\n  v_balance numeric := 0;\nbegin\n  select * into v_order from public.orders where id=p_order_id for update;\n  if not found then raise exception 'ORDER_NOT_FOUND'; end if;\n\n  select * into v_payment from public.payments where order_id=p_order_id order by created_at desc limit 1 for update;\n  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;\n\n  v_meta := coalesce(v_order.metadata,'{}'::jsonb);\n  if coalesce(v_meta->>'product_type',v_meta->>'kind') <> 'digital_content' then\n    raise exception 'INVALID_DIGITAL_CONTENT_ORDER';\n  end if;\n\n  select * into v_product from public.digital_content_products where id=(v_meta->>'product_id')::uuid for update;\n  if not found then raise exception 'PRODUCT_NOT_FOUND'; end if;\n\n  select * into v_sale from public.digital_content_sales where order_id=v_order.id for update;\n  if not found then raise exception 'SALE_NOT_FOUND'; end if;\n\n  if p_payment_status='paid' then\n    select * into v_rule from public.fans_fee_rules\n    where active=true and effective_from<=now() and (effective_until is null or effective_until>now())\n    order by effective_from desc limit 1;\n\n    v_platform_fee := least(\n      v_order.total,\n      round((v_order.total*coalesce(v_rule.platform_percent,0)/100)+coalesce(v_rule.fixed_fee,0),2)\n    );\n    v_owner_amount := greatest(round(v_order.total-v_provider_fee-v_platform_fee,2),0);\n    v_total_fees := greatest(round(v_order.total-v_owner_amount,2),0);\n\n    update public.payments\n       set provider=p_provider,\n           provider_payment_id=p_provider_payment_id,\n           status='paid',\n           payment_method=p_payment_method,\n           paid_at=coalesce(paid_at,now()),\n           updated_at=now()\n     where id=v_payment.id;\n\n    update public.orders\n       set status='paid', updated_at=now()\n     where id=v_order.id and status in ('awaiting_payment','paid');\n\n    update public.digital_content_sales\n       set status='paid',\n           platform_fee=v_platform_fee,\n           owner_amount=v_owner_amount,\n           provider=p_provider,\n           provider_reference=p_provider_payment_id,\n           paid_at=coalesce(paid_at,now()),\n           updated_at=now()\n     where id=v_sale.id;\n\n    insert into public.ledger_entries(\n      user_id,order_id,payment_id,entry_type,amount,currency,balance_after,\n      description,idempotency_key,metadata\n    )\n    select\n      v_product.owner_user_id,\n      v_order.id,\n      v_payment.id,\n      'credit'::ledger_entry_type,\n      v_owner_amount,\n      v_order.currency,\n      coalesce(sum(case when entry_type in ('credit','adjustment') then amount else -amount end),0)+v_owner_amount,\n      'Venda de conteúdo digital',\n      'digital-content-sale:'||v_sale.id::text,\n      jsonb_build_object(\n        'source','pecatho',\n        'kind','digital_content',\n        'product_id',v_product.id,\n        'sale_id',v_sale.id,\n        'gross_amount',v_order.total,\n        'platform_fee',v_platform_fee,\n        'provider_fee',v_provider_fee,\n        'owner_amount',v_owner_amount\n      )\n    from public.ledger_entries\n    where user_id=v_product.owner_user_id\n    on conflict (idempotency_key) do nothing;\n\n    if v_total_fees > 0 then\n      insert into public.ledger_entries(\n        user_id,order_id,payment_id,entry_type,amount,currency,balance_after,\n        description,idempotency_key,metadata\n      )\n      select\n        v_product.owner_user_id,\n        v_order.id,\n        v_payment.id,\n        'fee'::ledger_entry_type,\n        v_total_fees,\n        v_order.currency,\n        coalesce(sum(case when entry_type in ('credit','adjustment') then amount else -amount end),0)-v_total_fees,\n        'Taxas da venda de conteúdo digital',\n        'digital-content-fee:'||v_sale.id::text,\n        jsonb_build_object(\n          'source','pecatho',\n          'kind','digital_content',\n          'product_id',v_product.id,\n          'sale_id',v_sale.id,\n          'gross_amount',v_order.total,\n          'platform_fee',v_platform_fee,\n          'provider_fee',v_provider_fee,\n          'total_fees',v_total_fees\n        )\n      from public.ledger_entries\n      where user_id=v_product.owner_user_id\n      on conflict (idempotency_key) do nothing;\n    end if;\n\n    select coalesce(sum(case when entry_type in ('credit','adjustment') then amount else -amount end),0)\n      into v_balance\n      from public.ledger_entries\n     where user_id=v_product.owner_user_id;\n\n    return jsonb_build_object(\n      'ok',true,'status','paid','sale_id',v_sale.id,\n      'owner_amount',v_owner_amount,'platform_fee',v_platform_fee,\n      'provider_fee',v_provider_fee,'balance',v_balance\n    );\n  end if;\n\n  if p_payment_status in ('refunded','chargeback') then\n    update public.payments\n       set provider=p_provider,\n           provider_payment_id=p_provider_payment_id,\n           status=p_payment_status,\n           updated_at=now()\n     where id=v_payment.id;\n\n    update public.orders\n       set status='refunded', updated_at=now()\n     where id=v_order.id;\n\n    update public.digital_content_sales\n       set status=p_payment_status, updated_at=now()\n     where id=v_sale.id;\n\n    select coalesce(v_sale.owner_amount,0) into v_owner_amount;\n\n    insert into public.ledger_entries(\n      user_id,order_id,payment_id,entry_type,amount,currency,balance_after,\n      description,idempotency_key,metadata\n    )\n    select\n      v_product.owner_user_id,\n      v_order.id,\n      v_payment.id,\n      case when p_payment_status='chargeback' then 'chargeback'::ledger_entry_type else 'refund'::ledger_entry_type end,\n      v_owner_amount,\n      v_order.currency,\n      coalesce(sum(case when entry_type in ('credit','adjustment') then amount else -amount end),0)-v_owner_amount,\n      case when p_payment_status='chargeback' then 'Chargeback de conteúdo digital' else 'Estorno de conteúdo digital' end,\n      'digital-content-reversal:'||v_sale.id::text||':'||p_payment_status,\n      jsonb_build_object(\n        'source','pecatho','kind','digital_content',\n        'product_id',v_product.id,'sale_id',v_sale.id,\n        'owner_amount_reversed',v_owner_amount,'status',p_payment_status\n      )\n    from public.ledger_entries\n    where user_id=v_product.owner_user_id\n    on conflict (idempotency_key) do nothing;\n\n    select coalesce(sum(case when entry_type in ('credit','adjustment') then amount else -amount end),0)\n      into v_balance\n      from public.ledger_entries\n     where user_id=v_product.owner_user_id;\n\n    return jsonb_build_object(\n      'ok',true,'status',p_payment_status,'sale_id',v_sale.id,\n      'owner_amount_reversed',v_owner_amount,'balance',v_balance\n    );\n  end if;\n\n  update public.payments\n     set provider=p_provider,\n         provider_payment_id=p_provider_payment_id,\n         status=p_payment_status,\n         payment_method=coalesce(p_payment_method,payment_method),\n         updated_at=now()\n   where id=v_payment.id;\n\n  if p_payment_status in ('failed','cancelled') then\n    update public.orders\n       set status=p_payment_status, updated_at=now()\n     where id=v_order.id and status='awaiting_payment';\n\n    update public.digital_content_sales\n       set status=p_payment_status, updated_at=now()\n     where id=v_sale.id and status='pending';\n  end if;\n\n  return jsonb_build_object('ok',true,'status',p_payment_status,'sale_id',v_sale.id);\nend;\n$function$\n
